import re

def parse_size(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    s = text.strip()
    if not s:
        raise ValueError("Input cannot be empty or pure whitespace")

    match = re.fullmatch(r"(\d+(?:\.\d*)?|\.\d+)\s*([a-zA-Z]+)", s)
    if not match:
        raise ValueError(f"Invalid format: {text!r}")

    num_str, unit_str = match.groups()
    unit = unit_str.lower()

    units = {
        "b": 1,
        "kb": 10**3,
        "kib": 2**10,
        "mb": 10**6,
        "mib": 2**20,
        "gb": 10**9,
        "gib": 2**30,
    }

    if unit not in units:
        raise ValueError(f"Unknown unit: {unit_str!r}")

    return round(float(num_str) * units[unit])
