def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    word_info = {}  # lower_word -> [count, first_index, original_word]

    for idx, word in enumerate(words):
        lower_word = word.lower()
        if lower_word not in word_info:
            word_info[lower_word] = [1, idx, word]
        else:
            word_info[lower_word][0] += 1

    sorted_words = sorted(
        word_info.values(), key=lambda item: (-item[0], item[1])
    )

    return [(item[2], item[0]) for item in sorted_words[:k]]
