import json
import math


def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid_count = 0
    services = {}

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue

        try:
            record = json.loads(stripped)
        except Exception:
            invalid_count += 1
            continue

        if not isinstance(record, dict):
            invalid_count += 1
            continue

        if (
            "service" not in record
            or "latency_ms" not in record
            or "status" not in record
        ):
            invalid_count += 1
            continue

        service = record["service"]
        latency_ms = record["latency_ms"]
        status = record["status"]

        if (
            not isinstance(service, str)
            or not isinstance(latency_ms, (int, float))
            or isinstance(latency_ms, bool)
            or not isinstance(status, (int, float))
            or isinstance(status, bool)
        ):
            invalid_count += 1
            continue

        if service not in services:
            services[service] = {"latencies": [], "ok_count": 0}

        services[service]["latencies"].append(latency_ms)
        if 200 <= status < 300:
            services[service]["ok_count"] += 1

    result = {"invalid": invalid_count}
    for svc_name in sorted(services.keys()):
        data = services[svc_name]
        latencies = sorted(data["latencies"])
        n = len(latencies)
        ok_rate = data["ok_count"] / n if n > 0 else 0.0
        if n == 0:
            p95 = None
        else:
            idx = math.ceil(0.95 * n) - 1
            p95 = latencies[idx]

        result[svc_name] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95,
        }

    return result
