import heapq


class CycleError(Exception):
    def __init__(self, cycle: list[str], message: str = "Cycle detected in dependency graph"):
        super().__init__(message)
        self.cycle = cycle


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    for u, v in edges:
        if u not in node_set or v not in node_set:
            raise ValueError(f"Unknown node in edge: ({u}, {v})")

    adj: dict[str, list[str]] = {n: [] for n in nodes}
    in_degree: dict[str, int] = {n: 0 for n in nodes}
    unique_edges = set(edges)

    for u, v in unique_edges:
        adj[u].append(v)
        in_degree[v] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) == len(nodes):
        return result

    # 存在环，寻找一个具体环路
    color = {n: 0 for n in nodes}  # 0: 未访问, 1: 访问中, 2: 已访问
    path: list[str] = []
    cycle: list[str] = []

    def dfs(u: str) -> bool:
        nonlocal cycle
        color[u] = 1
        path.append(u)
        for v in adj[u]:
            if color[v] == 1:
                idx = path.index(v)
                cycle = path[idx:] + [v]
                return True
            elif color[v] == 0:
                if dfs(v):
                    return True
        path.pop()
        color[u] = 2
        return False

    for n in sorted(nodes):
        if color[n] == 0:
            if dfs(n):
                break

    raise CycleError(cycle=cycle)

