import copy


def apply_patch_ops(document: dict, operations) -> dict:
    if not isinstance(document, dict):
        raise TypeError("Document must be a dictionary")

    doc_copy = copy.deepcopy(document)

    for op, path, value in operations:
        if not isinstance(path, str) or not path:
            raise ValueError(f"Invalid path: {path}")

        keys = path.split(".")

        if op == "set":
            curr = doc_copy
            for key in keys[:-1]:
                if key not in curr:
                    curr[key] = {}
                elif not isinstance(curr[key], dict):
                    raise TypeError(
                        f"Cannot set path '{path}': '{key}' is not a dict"
                    )
                curr = curr[key]
            if not isinstance(curr, dict):
                raise TypeError(
                    f"Cannot set path '{path}': target parent is not a dict"
                )
            curr[keys[-1]] = copy.deepcopy(value)

        elif op == "delete":
            curr = doc_copy
            found = True
            for key in keys[:-1]:
                if not isinstance(curr, dict) or key not in curr:
                    found = False
                    break
                curr = curr[key]
            if found and isinstance(curr, dict):
                curr.pop(keys[-1], None)

        elif op == "increment":
            if type(value) not in (int, float):
                raise TypeError(
                    f"Increment value must be int or float, got {type(value).__name__}"
                )

            curr = doc_copy
            for key in keys[:-1]:
                if not isinstance(curr, dict) or key not in curr:
                    raise KeyError(f"Path '{path}' not found for increment")
                curr = curr[key]

            if not isinstance(curr, dict):
                raise TypeError(
                    f"Cannot increment path '{path}': target parent is not a dict"
                )

            last_key = keys[-1]
            if last_key not in curr:
                raise KeyError(f"Path '{path}' not found for increment")

            target_val = curr[last_key]
            if type(target_val) not in (int, float):
                raise TypeError(
                    f"Target value at '{path}' is not a number, got {type(target_val).__name__}"
                )

            curr[last_key] = target_val + value

        else:
            raise ValueError(f"Unsupported operation: '{op}'")

    return doc_copy
