import threading
import time
from typing import Any, Callable, Optional


class _Call:

    def __init__(self):
        self.event = threading.Event()
        self.val: Any = None
        self.err: Optional[BaseException] = None


class SingleFlightTTLCache:

    def __init__(self, default_ttl: Optional[float] = None):
        self.default_ttl = default_ttl
        self._cache: dict[Any, tuple[Any, float]] = {}
        self._inflight: dict[Any, _Call] = {}
        self._lock = threading.Lock()

    def _is_expired(self, expire_time: float) -> bool:
        return time.monotonic() >= expire_time

    def get(self, key: Any, default: Any = None) -> Any:
        with self._lock:
            if key in self._cache:
                val, expire_time = self._cache[key]
                if not self._is_expired(expire_time):
                    return val
                del self._cache[key]
            return default

    def set(self, key: Any, value: Any, ttl: Optional[float] = None) -> None:
        effective_ttl = ttl if ttl is not None else self.default_ttl
        expire_time = (
            time.monotonic() + effective_ttl
            if effective_ttl is not None
            else float("inf")
        )
        with self._lock:
            self._cache[key] = (value, expire_time)

    def delete(self, key: Any) -> bool:
        with self._lock:
            return self._cache.pop(key, None) is not None

    def __len__(self) -> int:
        with self._lock:
            now = time.monotonic()
            expired_keys = [
                k for k, (_, exp) in self._cache.items() if now >= exp
            ]
            for k in expired_keys:
                del self._cache[k]
            return len(self._cache)

    def get_or_load(
        self, key: Any, loader: Callable[[], Any], ttl: Optional[float] = None
    ) -> Any:
        with self._lock:
            if key in self._cache:
                val, expire_time = self._cache[key]
                if not self._is_expired(expire_time):
                    return val
                del self._cache[key]

            if key in self._inflight:
                call = self._inflight[key]
                is_leader = False
            else:
                call = _Call()
                self._inflight[key] = call
                is_leader = True

        if not is_leader:
            call.event.wait()
            if call.err is not None:
                raise call.err
            return call.val

        try:
            val = loader()
            effective_ttl = ttl if ttl is not None else self.default_ttl
            expire_time = (
                time.monotonic() + effective_ttl
                if effective_ttl is not None
                else float("inf")
            )
            with self._lock:
                self._cache[key] = (val, expire_time)
                call.val = val
                self._inflight.pop(key, None)
        except BaseException as e:
            with self._lock:
                call.err = e
                self._inflight.pop(key, None)
        finally:
            call.event.set()

        if call.err is not None:
            raise call.err
        return call.val
