import asyncio
from typing import Any, Iterable, List, Tuple


async def run_with_deadline(
    coros: Iterable[Any], limit: int, timeout: float
) -> List[Tuple[str, Any]]:
    coro_list = list(coros)
    if not coro_list:
        return []

    limit = max(1, limit)
    sem = asyncio.Semaphore(limit)
    results: List[Any] = [None] * len(coro_list)

    async def worker(idx: int, coro: Any) -> None:
        try:
            async with sem:
                try:
                    res = await coro
                    results[idx] = ("ok", res)
                except asyncio.CancelledError as e:
                    results[idx] = ("cancelled", e)
                    raise
                except Exception as e:
                    results[idx] = ("error", e)
        except asyncio.CancelledError as e:
            if results[idx] is None:
                results[idx] = ("cancelled", e)
            raise

    tasks = [asyncio.create_task(worker(i, c)) for i, c in enumerate(coro_list)]

    try:
        await asyncio.wait_for(asyncio.gather(*tasks), timeout=timeout)
    except (asyncio.TimeoutError, asyncio.CancelledError):
        for t in tasks:
            if not t.done():
                t.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)

    for i in range(len(coro_list)):
        if results[i] is None:
            results[i] = ("cancelled", asyncio.CancelledError())

    return results
