import threading


class IdempotentEventProcessor:
    class _Task:
        def __init__(self):
            self.event = threading.Event()
            self.result = None
            self.exception = None
            self.is_success = False

    def __init__(self, apply):
        self._apply = apply
        self._lock = threading.Lock()
        self._results = {}
        self._in_progress = {}

    def process(self, event_id, payload):
        while True:
            with self._lock:
                if event_id in self._results:
                    return self._results[event_id]

                if event_id in self._in_progress:
                    task = self._in_progress[event_id]
                    is_leader = False
                else:
                    task = self._Task()
                    self._in_progress[event_id] = task
                    is_leader = True

            if is_leader:
                try:
                    res = self._apply(payload)
                    with self._lock:
                        self._results[event_id] = res
                        self._in_progress.pop(event_id, None)
                    task.result = res
                    task.is_success = True
                    task.event.set()
                    return res
                except BaseException as exc:
                    with self._lock:
                        if self._in_progress.get(event_id) is task:
                            self._in_progress.pop(event_id, None)
                    task.exception = exc
                    task.event.set()
                    raise
            else:
                task.event.wait()
                if task.is_success:
                    return task.result
                else:
                    raise task.exception

    def result(self, event_id):
        with self._lock:
            if event_id in self._results:
                return self._results[event_id]
        raise KeyError(f"Event {event_id!r} has not been processed successfully.")
