import copy
import threading
from typing import Any, Dict, Optional, Tuple


class VersionedStore:
    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._store: Dict[Any, Tuple[Any, int]] = {}

    def read(self, key: Any) -> Optional[Tuple[Any, int]]:
        with self._lock:
            if key not in self._store:
                return None
            val, ver = self._store[key]
            return copy.deepcopy(val), ver

    def compare_and_set(self, key: Any, expected_version: int, value: Any) -> bool:
        with self._lock:
            if key not in self._store:
                if expected_version == 0:
                    self._store[key] = (copy.deepcopy(value), 1)
                    return True
                return False

            _, current_version = self._store[key]
            if current_version == expected_version:
                self._store[key] = (copy.deepcopy(value), current_version + 1)
                return True
            return False

    def delete(self, key: Any, expected_version: int) -> bool:
        with self._lock:
            if key not in self._store:
                return False

            _, current_version = self._store[key]
            if current_version == expected_version:
                del self._store[key]
                return True
            return False

    def snapshot(self) -> Dict[Any, Tuple[Any, int]]:
        with self._lock:
            return {
                copy.deepcopy(k): (copy.deepcopy(v), ver)
                for k, (v, ver) in self._store.items()
            }
