from dataclasses import dataclass
from typing import Any, List, Optional, Tuple


@dataclass(frozen=True)
class LogEntry:
    term: int
    command: Any


class ReplicatedLog:
    def __init__(self, initial_term: int = 0):
        self._term: int = initial_term
        # index 0 is a dummy sentinel entry (1-based index)
        self._log: List[LogEntry] = [LogEntry(term=0, command=None)]
        self._commit_index: int = 0
        self._last_applied: int = 0

    def current_term(self) -> int:
        return self._term

    def current_index(self) -> int:
        return len(self._log) - 1

    def append(self, command: Any, term: Optional[int] = None) -> int:
        """Appends a command to local log in the current term (or specified term)."""
        if term is not None:
            if term < self._term:
                raise ValueError("Cannot append with a term lower than current term")
            self._term = term
        self._log.append(LogEntry(term=self._term, command=command))
        return self.current_index()

    def receive_append(
        self,
        term: int,
        prev_index: int,
        prev_term: int,
        entries: List[Tuple[int, Any]],
        leader_commit: int,
    ) -> Tuple[bool, int]:
        """
        Processes AppendEntries from leader.
        Returns:
            (True, match_index) on success.
            (False, conflict_index) on failure.
        """
        # 1. Reject stale terms
        if term < self._term:
            return False, self.current_index() + 1

        if term > self._term:
            self._term = term

        # 2. Check if log contains an entry at prev_index matching prev_term
        if prev_index < 0:
            return False, 0

        if prev_index > self.current_index():
            # Missing entries; hint next expected index
            return False, self.current_index() + 1

        if self._log[prev_index].term != prev_term:
            # Term mismatch; conflict at prev_index
            return False, prev_index

        # 3. Process entries: overwrite conflicting suffix idempotently
        insert_idx = prev_index + 1
        for i, (e_term, e_cmd) in enumerate(entries):
            target_idx = insert_idx + i
            new_entry = LogEntry(term=e_term, command=e_cmd)
            if target_idx <= self.current_index():
                if self._log[target_idx] != new_entry:
                    # Conflict found: truncate everything from target_idx onwards
                    del self._log[target_idx:]
                    self._log.append(new_entry)
            else:
                self._log.append(new_entry)

        # 4. Update commit index (cannot exceed current local log length)
        if leader_commit > self._commit_index:
            self._commit_index = max(
                self._commit_index, min(leader_commit, self.current_index())
            )

        return True, self.current_index()

    def commit_to(self, index: int) -> None:
        """Advances commit index monotonically, capped by local log length."""
        capped_index = min(index, self.current_index())
        if capped_index > self._commit_index:
            self._commit_index = capped_index

    def apply_committed(self) -> List[Any]:
        """Applies newly committed entries in order. Idempotent and re-entrant."""
        if self._last_applied >= self._commit_index:
            return []

        applied_commands = [
            self._log[i].command
            for i in range(self._last_applied + 1, self._commit_index + 1)
        ]
        self._last_applied = self._commit_index
        return applied_commands


# ==============================================================================
# 5 组关键测试用例说明（针对边界条件与一致性缺陷）：
#
# 1. 冲突覆盖截断测试（Suffix Truncation on Conflict）：
#    - 场景：本地 log 在 index=2 处为 Term 1，Leader 发送 prev_index=1, prev_term=1,
#           entries=[(Term 2, "cmd2_new")]。
#    - 验证：本地 index=2 及之后的旧 Term 1 条目被正确覆盖截断，日志不出现分叉或残留。
#
# 2. 幂等与重复消息测试（Duplicate A
